float d01 = std::inner_product(v0.begin(), v0.end(), v1.begin(), 0.0f);
float d11 = std::inner_product(v1.begin(), v1.end(), v1.begin(), 0.0f);
float d20 = std::inner_product(v2.begin(), v2.end(), v0.begin(), 0.0f);
float d21 = std::inner_product(v2.begin(), v2.end(), v1.begin(), 0.0f);

float denom = d00 * d11 - d01 * d01;
float v = (d11 * d20 - d01 * d21) / denom;
float w = (d00 * d21 - d01 * d20) / denom;
float u = 1.0f - v - w;

return {u, v, w};
